(window.G3D=window.G3D||{})[2]=[{"id":"g3-040","n":40,"u":2,"st":"다음 빈칸에 들어갈 말로 알맞지 않은 것은?","ty":"알맞은 말 고르기","core":"as + 부사 + as · 동사 write를 꾸미는 부사","ans":[3],"kind":"sent","pol":"bad","body":"The girl can write the sentences as ____________ as the boy.","bko":"그 소녀는 그 소년만큼 ~하게 문장을 쓸 수 있다.","opts":[{"t":"fast","ko":"빠르게","ok":true,"fix":"","why":"fast는 ‘빠른’이라는 형용사도 되고 ‘빠르게’라는 부사도 된다. 여기서는 동사 write(원형 write 쓰다)를 꾸미는 부사로 쓰여 as fast as(~만큼 빠르게)가 자연스럽다."},{"t":"well","ko":"잘","ok":true,"fix":"","why":"well은 ‘잘’이라는 뜻의 부사이다. as well as(~만큼 잘)로 write를 꾸미므로 알맞다."},{"t":"easily","ko":"쉽게","ok":true,"fix":"","why":"easily는 ‘쉽게’라는 뜻의 부사이다. as easily as(~만큼 쉽게)로 write를 꾸미므로 알맞다."},{"t":"fluent","ko":"유창한","ok":false,"fix":"fluently(유창하게)","why":"‘as ~ as’ 사이에는 ‘얼마나 그렇게 쓸 수 있는지’를 말해 주는 부사가 와야 한다(동사 write를 꾸미므로). fluent(유창한)는 형용사라서 어울리지 않고, 부사 fluently(유창하게)로 고쳐야 한다."},{"t":"quickly","ko":"빠르게","ok":true,"fix":"","why":"quickly는 ‘빠르게’라는 뜻의 부사이다. as quickly as(~만큼 빠르게)로 write를 꾸미므로 알맞다."}],"vb":["write → 원형 write 쓰다"]},{"id":"g3-041","n":41,"u":2,"st":"다음 중 빈칸에 들어갈 말이 나머지와 다른 것은?","ty":"다른 것 찾기","core":"형용사 + enough + to부정사 · too ~ to부정사","ans":[2],"kind":"sent","pol":"good","nolabel":true,"opts":[{"t":"The boy is fast enough to win the race.","ko":"그 소년은 경주에서 이길 만큼 충분히 빠르다.","ok":true,"fix":"","why":"빈칸에는 enough가 들어간다. ‘형용사 + enough + to부정사(to + 동사원형)’는 ‘~할 만큼 충분히 -하다’라는 뜻이다. win(원형 win 이기다)."},{"t":"He is smart enough to understand the problem.","ko":"그는 그 문제를 이해할 만큼 충분히 똑똑하다.","ok":true,"fix":"","why":"빈칸에는 enough가 들어간다. ‘충분히 똑똑해서 이해할 수 있다’는 뜻이다. understand(원형 understand 이해하다)."},{"t":"The marble table is too heavy for me to carry.","ko":"그 대리석 탁자는 너무 무거워서 내가 들 수 없다.","ok":true,"fix":"","why":"빈칸에는 too가 들어간다. ‘too ~ to부정사’는 ‘너무 ~해서 -할 수 없다’라는 뜻이다. 탁자가 ‘충분히 무겁다’는 말은 어색하고, 너무 무거워서 들 수 없다는 뜻이므로 나머지(enough)와 다르다. for me는 to carry(원형 carry 나르다)의 의미상 주어(행동하는 사람)이다."},{"t":"This rice cake is big enough for all of us to eat.","ko":"이 떡은 우리 모두가 먹을 만큼 충분히 크다.","ok":true,"fix":"","why":"빈칸에는 enough가 들어간다. for all of us는 to eat(원형 eat 먹다)의 의미상 주어이다."},{"t":"The weather is warm enough for us to play outside.","ko":"날씨가 우리가 밖에서 놀 만큼 충분히 따뜻하다.","ok":true,"fix":"","why":"빈칸에는 enough가 들어간다. for us는 to play(원형 play 놀다)의 의미상 주어이다."}],"vb":["win → 원형 win 이기다","understand → 원형 understand 이해하다","carry → 원형 carry 나르다","eat → 원형 eat 먹다","play → 원형 play 놀다"]},{"id":"g3-046","n":46,"u":2,"st":"다음 밑줄 친 단어의 쓰임이 어색한 것은?","ty":"틀린 것 찾기","core":"동사를 꾸미는 부사 · 형용사와 부사 구별","ans":[1],"kind":"sent","pol":"bad","opts":[{"t":"You can answer this question easily.","ko":"너는 이 질문에 쉽게 대답할 수 있다. (밑줄: easily)","ok":true,"fix":"","why":"easily(쉽게)는 동사 answer(원형 answer 대답하다)를 꾸미는 부사이므로 알맞다."},{"t":"To stay healthy, you need to exercise regular.","ko":"건강을 유지하려면 너는 규칙적으로 운동할 필요가 있다. (밑줄: regular)","ok":false,"fix":"To stay healthy, you need to exercise regularly.","why":"동사 exercise(원형 exercise 운동하다)를 꾸밀 때는 부사가 와야 한다. regular(규칙적인)는 형용사이므로 부사 regularly(규칙적으로)로 고쳐야 한다."},{"t":"Many people tried to help, but you’re the most helpful.","ko":"많은 사람들이 도우려 했지만, 네가 가장 도움이 된다. (밑줄: helpful)","ok":true,"fix":"","why":"you’re(= you are) 뒤에서 주어 you를 설명하는 보어 자리이므로 형용사 helpful(도움이 되는)이 알맞다. tried(원형 try 노력하다)."},{"t":"Using the method wisely, you can solve many problems.","ko":"그 방법을 현명하게 사용하면 너는 많은 문제를 풀 수 있다. (밑줄: wisely)","ok":true,"fix":"","why":"wisely(현명하게)는 동사 using(원형 use 사용하다)을 꾸미는 부사이므로 알맞다. solve(원형 solve 풀다)."},{"t":"You can’t possibly understand how I felt because you’ve never been in that situation.","ko":"너는 그런 상황에 처해 본 적이 없어서 내가 어떻게 느꼈는지 도저히 이해할 수 없다. (밑줄: possibly)","ok":true,"fix":"","why":"possibly(도저히, 아무리 해도)는 can’t와 함께 쓰여 동사 understand(원형 understand 이해하다)를 강조하는 부사이므로 알맞다. felt(원형 feel 느끼다)."}],"vb":["tried → 원형 try 노력하다 (과거형 tried)","felt → 원형 feel 느끼다 (과거형 felt)","answer → 원형 answer 대답하다","exercise → 원형 exercise 운동하다","using → 원형 use 사용하다","solve → 원형 solve 풀다","understand → 원형 understand 이해하다"]},{"id":"g3-049","n":49,"u":2,"st":"다음 중 나머지와 넷과 의미가 다른 것은?","ty":"다른 것 찾기","core":"원급·비교급·최상급의 의미 바꿔 쓰기","ans":[3],"kind":"sent","pol":"good","nolabel":true,"opts":[{"t":"Jinsu is the tallest boy in his class.","ko":"진수는 그의 반에서 가장 키가 큰 소년이다.","ok":true,"fix":"","why":"최상급(the + -est)으로 ‘반에서 가장 키가 크다’는 뜻이다."},{"t":"No boy in his class is as tall as Jinsu.","ko":"그의 반에서 어떤 소년도 진수만큼 키가 크지 않다.","ok":true,"fix":"","why":"‘No + 명사 + as ~ as’는 ‘어떤 -도 …만큼 ~하지 않다’라는 뜻이라서 결국 진수가 가장 크다는 말이다."},{"t":"No boy in his class is taller than Jinsu.","ko":"그의 반에서 어떤 소년도 진수보다 키가 크지 않다.","ok":true,"fix":"","why":"‘No + 명사 + 비교급 + than’도 ‘어떤 -도 …보다 더 ~하지 않다’라는 뜻이라서 진수가 가장 크다는 말이다."},{"t":"Jinsu isn’t as tall as other boys in his class.","ko":"진수는 그의 반의 다른 소년들만큼 키가 크지 않다.","ok":true,"fix":"","why":"‘A is not as ~ as B’는 ‘A는 B만큼 ~하지 않다’라는 뜻이다. 즉 진수가 다른 소년들보다 키가 작다는 말이라서 나머지 넷과 의미가 다르다."},{"t":"Jinsu is taller than any other boy in his class.","ko":"진수는 그의 반의 다른 어떤 소년보다 키가 크다.","ok":true,"fix":"","why":"‘비교급 + than any other + 단수명사’는 ‘다른 어떤 -보다 더 ~하다’라는 뜻이라서 진수가 가장 크다는 말이다."}]},{"id":"g3-051","n":51,"u":2,"st":"다음 두 문장을 한 문장으로 바꾼 것 중 옳지 않은 것은? (정답2개)","ty":"틀린 것 찾기","core":"원급 부정 · 비교급 문장 바꿔 쓰기","ans":[1,4],"kind":"sent","pol":"bad","opts":[{"t":"I’m pretty tall. You are taller than me. → I’m not as tall as you.","ko":"나는 꽤 키가 크다. 너는 나보다 더 크다. → 나는 너만큼 키가 크지 않다.","ok":true,"fix":"","why":"내가 너보다 작으므로 ‘나는 너만큼 크지 않다’는 맞다. ‘not as ~ as’는 ‘~만큼 -하지 않다’라는 뜻이다."},{"t":"Sarah has $10 million. Eric has $8 million. → Eric is richer than Sarah.","ko":"Sarah는 1000만 달러를 가지고 있다. Eric은 800만 달러를 가지고 있다. → Eric이 Sarah보다 더 부자이다.","ok":false,"fix":"Sarah is richer than Eric.","why":"돈이 더 많은 사람은 Sarah(1000만 달러)이다. 그러므로 Sarah is richer than Eric.으로 써야 한다. has(원형 have 가지다)."},{"t":"You know a little bit about cars. I know more. → You don’t know about cars as much as I do.","ko":"너는 자동차에 대해 조금 안다. 나는 더 많이 안다. → 너는 나만큼 자동차에 대해 알지 못한다.","ok":true,"fix":"","why":"내가 더 많이 아니까 ‘너는 나만큼 모른다’는 맞다. 뒤의 do는 know(원형 know 알다)를 대신하는 말이다."},{"t":"The blue hat is $20. The red hat is also $20. → The blue hat is as expensive as the red hat.","ko":"파란 모자는 20달러이다. 빨간 모자도 20달러이다. → 파란 모자는 빨간 모자만큼 비싸다.","ok":true,"fix":"","why":"가격이 같으므로 ‘as + 형용사 + as(~만큼 -하다)’를 쓴 문장이 맞다."},{"t":"Jason runs 100m in 15 seconds. Mike runs 100m in 20seconds. → Jason runs not so fast as Mike.","ko":"Jason은 100m를 15초에 달린다. Mike는 100m를 20초에 달린다. → Jason은 Mike만큼 빠르게 달리지 않는다.","ok":false,"fix":"Jason runs faster than Mike.","why":"15초에 달리는 Jason이 더 빠르다. 그러므로 Jason runs faster than Mike.로 써야 한다. runs(원형 run 달리다)."}],"vb":["has → 원형 have 가지다 (3인칭 단수 현재형 has)","runs → 원형 run 달리다 (3인칭 단수 현재형 runs)","know → 원형 know 알다"]},{"id":"g3-052","n":52,"u":2,"st":"다음 글의 빈칸 (A)~(D)에 어법상 들어갈 표현으로 가장 적절하게 짝지은 것은?","ty":"조합 고르기","core":"가주어 It–진주어 to부정사 · 비교급 강조 a lot · 수일치 · 수동태","ans":[3],"kind":"abc","body":"Where have all the honey bees gone? It is really hard (A)____________ them these days. The bees are disappearing! About a third of the bee population dies every year. This is bad news for bees, but it’s (B)____________ worse news for people.<br>Bees are very helpful to humans. First, bees give us honey. Honey is a truly wonderful food. It is good for our health and (C)____________ great. Honey can last almost forever. In fact, honey from ancient Egypt can be eaten today! Second, bees help produce many crops such as apples and strawberries. These crops cannot (D)____________ by themselves. They need the help of bees. Bees help in the process of pollination.","bko":"꿀벌들은 모두 어디로 갔을까? 요즘은 꿀벌을 보기가 정말 어렵다. 꿀벌들이 사라지고 있다! 꿀벌 개체 수의 약 3분의 1이 해마다 죽는다. 이것은 벌에게 나쁜 소식이지만, 사람에게는 훨씬 더 나쁜 소식이다.\n벌은 인간에게 매우 도움이 된다. 첫째, 벌은 우리에게 꿀을 준다. 꿀은 정말 훌륭한 음식이다. 꿀은 우리 건강에 좋고 맛도 아주 좋다. 꿀은 거의 영원히 보존될 수 있다. 실제로 고대 이집트의 꿀도 오늘날 먹을 수 있다! 둘째, 벌은 사과와 딸기 같은 많은 작물을 생산하는 것을 돕는다. 이 작물들은 스스로 생산될 수 없다. 그것들은 벌의 도움이 필요하다. 벌은 수분 과정에서 도움을 준다.","opts":[{"t":"see still taste produce","ko":"(A) see 보다 / (B) still 여전히 / (C) taste 맛이 나다(원형) / (D) produce 생산하다(원형)","fix":"","why":""},{"t":"see even tastes produce","ko":"(A) see 보다 / (B) even 훨씬 / (C) tastes 맛이 나다 / (D) produce 생산하다(원형)","fix":"","why":""},{"t":"to see very taste produced","ko":"(A) to see 보는 것 / (B) very 매우 / (C) taste 맛이 나다(원형) / (D) produced 생산했다","fix":"","why":""},{"t":"to see a lot tastes be produced","ko":"(A) to see 보는 것 / (B) a lot 훨씬 / (C) tastes 맛이 나다 / (D) be produced 생산되다","fix":"","why":""},{"t":"to see much taste be produced","ko":"(A) to see 보는 것 / (B) much 훨씬 / (C) taste 맛이 나다(원형) / (D) be produced 생산되다","fix":"","why":""}],"blob":"(A) It is hard 뒤에는 가주어 It이 가리키는 진짜 주어(진주어)가 필요하다. ‘~하는 것’을 나타내는 to부정사(to + 동사원형) to see(원형 see 보다)가 알맞다. (B) worse는 bad(나쁜)의 비교급(더 나쁜)이다. 비교급을 꾸며 ‘훨씬’이라는 뜻을 더하려면 a lot, much, even, still, far를 쓰고, very는 쓰지 않는다. 따라서 a lot이 알맞다(보기 ⑤의 much도 (B)로는 가능하지만 (C)에서 taste가 틀려 정답이 될 수 없다). (C) 앞에서 It is good for our health and … great라고 했다. 주어 It 뒤에 동사가 필요하고, It은 3인칭 단수이므로 tastes(원형 taste 맛이 나다)가 알맞다. and가 두 동사 is와 tastes를 나란히 이어 준다. (D) 주어 These crops(이 작물들)는 ‘생산하는’ 쪽이 아니라 ‘생산되는’ 쪽이다. 그러므로 수동태(be + 과거분사, ~되다) be produced(원형 produce 생산하다)가 알맞다. cannot 뒤이므로 be가 필요하다. 따라서 정답은 to see – a lot – tastes – be produced이다.","vb":["see → 원형 see 보다","tastes → 원형 taste 맛이 나다 (3인칭 단수 현재형 tastes)","produced → 원형 produce 생산하다 (be produced 생산되다)"]},{"id":"g3-053","n":53,"u":2,"st":"다음 글의 밑줄 친 ⓐ~ⓔ 중 어법상 옳지 않은 것은?","ty":"틀린 것 찾기","core":"a few + 복수명사 · 주격 관계대명사 수일치 · 가정법 과거 · name A B","ans":[3],"kind":"seg","pol":"bad","body":"When I was five, my little sister Olivia and I each adopted a cheetah. Did we raise cheetahs at home? No, we donated to <b class=\"lb\">ⓐ</b><u>a charity that protects</u> wild cheetahs in South Africa. Our parents told us that <b class=\"lb\">ⓑ</b><u>if we did not protect</u> them, we <b class=\"lb\">ⓒ</b><u>might not be</u> able to see cheetahs in the near future.<br>We soon became interested in helping other endangered animals. <b class=\"lb\">ⓓ</b><u>Few years</u> later, with help from our parents, we created a non-profit organization to protect them. We wanted the next generation to be able to see these animals, so we <b class=\"lb\">ⓔ</b><u>named our organization One More Generation</u>. We studied endangered animals and educated our friends about them.","bko":"내가 다섯 살 때, 내 어린 여동생 올리비아와 나는 각자 치타를 한 마리씩 입양했다. 우리가 집에서 치타를 길렀을까? 아니다, 우리는 남아프리카 공화국의 야생 치타를 보호하는 자선단체에 기부했다. 부모님은 우리가 치타를 보호하지 않으면 가까운 미래에 치타를 볼 수 없을지도 모른다고 말씀하셨다.\n우리는 곧 다른 멸종 위기 동물을 돕는 데 관심을 갖게 되었다. 몇 년 후, 부모님의 도움으로 우리는 그들을 보호하기 위한 비영리 단체를 만들었다. 우리는 다음 세대가 이 동물들을 볼 수 있기를 바랐고, 그래서 우리 단체의 이름을 ‘원 모어 제너레이션’이라고 지었다. 우리는 멸종 위기 동물에 대해 공부했고 친구들에게 그들에 대해 가르쳐 주었다.","opts":["ⓐ","ⓑ","ⓒ","ⓓ","ⓔ"],"segs":[{"k":"ⓐ","en":"a charity that protects","ko":"야생 치타를 보호하는 자선단체","ok":true,"fix":"","why":"that은 앞의 a charity(자선단체)를 꾸미는 주격 관계대명사(앞말을 설명하며 주어 역할을 하는 말)이다. a charity가 단수이므로 동사도 단수형 protects(원형 protect 보호하다)로 맞췄다. 따라서 적절하다."},{"k":"ⓑ","en":"if we did not protect","ko":"우리가 보호하지 않는다면","ok":true,"fix":"","why":"현재 사실과 반대로 가정하는 문장(가정법 과거)에서 if절의 동사는 과거형으로 쓴다. 그러므로 did not protect(원형 protect 보호하다)는 적절하다."},{"k":"ⓒ","en":"might not be","ko":"~하지 못할지도 모른다","ok":true,"fix":"","why":"가정법 과거의 주절은 ‘조동사의 과거형 + 동사원형’으로 쓴다. might not 뒤에 be(원형 be ~이다)가 왔으므로 적절하다."},{"k":"ⓓ","en":"Few years","ko":"몇 년 (후에)","ok":false,"fix":"A few years","why":"‘몇 년 후에’라는 뜻은 a few years later로 쓴다. a few는 ‘몇 개의’라는 뜻이고, 관사 없이 few만 쓰면 ‘거의 없는’이라는 뜻이 되어 어색하다. 따라서 Few years는 A few years가 적절하다."},{"k":"ⓔ","en":"named our organization One More Generation","ko":"우리 단체의 이름을 ‘원 모어 제너레이션’이라고 지었다.","ok":true,"fix":"","why":"‘name A B’는 ‘A를 B라고 이름 짓다’라는 뜻이다. our organization(A)이 목적어, One More Generation(B)이 이름이므로 named(원형 name 이름 짓다)는 적절하다."}],"vb":["adopted → 원형 adopt 입양하다 (과거형 adopted)","protects → 원형 protect 보호하다 (3인칭 단수 현재형 protects)","named → 원형 name 이름 짓다 (과거형 named)"]},{"id":"g3-054","n":54,"u":2,"st":"다음 중 단어의 연결 관계가 나머지와 다른 하나는?","ty":"다른 것 찾기","core":"형용사 + ly = 부사 · 명사 + ly = 형용사","ans":[0],"kind":"sent","pol":"good","nolabel":true,"opts":[{"t":"love – lovely","ko":"사랑 – 사랑스러운","ok":true,"fix":"","why":"love(사랑)는 명사이고 여기에 ly를 붙인 lovely(사랑스러운)는 형용사이다. ‘명사 + ly’는 형용사가 되므로 나머지와 다르다."},{"t":"easy – easily","ko":"쉬운 – 쉽게","ok":true,"fix":"","why":"easy(쉬운)는 형용사이고 y를 i로 바꾸고 ly를 붙인 easily(쉽게)는 부사이다. ‘형용사 + ly’는 부사가 된다."},{"t":"careful – carefully","ko":"조심스러운 – 조심스럽게","ok":true,"fix":"","why":"careful(조심스러운)은 형용사이고 carefully(조심스럽게)는 부사이다. ‘형용사 + ly’는 부사가 된다."},{"t":"complete – completely","ko":"완전한 – 완전히","ok":true,"fix":"","why":"complete(완전한)는 형용사이고 completely(완전히)는 부사이다. ‘형용사 + ly’는 부사가 된다."},{"t":"immediate – immediately","ko":"즉각적인 – 즉시","ok":true,"fix":"","why":"immediate(즉각적인)는 형용사이고 immediately(즉시)는 부사이다. ‘형용사 + ly’는 부사가 된다."}]},{"id":"g3-055","n":55,"u":2,"st":"다음 중 밑줄 친 부분이 어법상 어색하게 쓰인 것은?","ty":"틀린 것 찾기","core":"look·feel + 형용사 · 보어 자리의 형용사","ans":[2],"kind":"seg","pol":"bad","body":"Today was <b class=\"lb\">ⓐ</b><u>rainy</u> day. So, we had to stay home all day long. My mom made us Kalguksu(Korean noodle) for lunch. It looked <b class=\"lb\">ⓑ</b><u>tasty</u> but <b class=\"lb\">ⓒ</b><u>hot and salt</u>. After lunch, we felt <b class=\"lb\">ⓓ</b><u>sleepy</u>. I hope tomorrow will be <b class=\"lb\">ⓔ</b><u>sunny</u>.","bko":"오늘은 비 오는 날이었다. 그래서 우리는 하루 종일 집에 있어야 했다. 엄마가 점심으로 칼국수(한국식 국수)를 만들어 주셨다. 맛있어 보였지만 뜨겁고 짰다. 점심 후에 우리는 졸렸다. 내일은 맑았으면 좋겠다.","opts":["ⓐ","ⓑ","ⓒ","ⓓ","ⓔ"],"segs":[{"k":"ⓐ","en":"rainy","ko":"비 오는","ok":true,"fix":"","why":"rainy(비 오는)는 뒤의 명사 day(날)를 꾸미는 형용사이므로 적절하다."},{"k":"ⓑ","en":"tasty","ko":"맛있는","ok":true,"fix":"","why":"looked(원형 look ~해 보이다) 뒤에는 보어(주어를 설명하는 말)로 형용사가 온다. ‘look + 형용사’는 ‘~해 보이다’라는 뜻이므로 형용사 tasty는 적절하다."},{"k":"ⓒ","en":"hot and salt","ko":"뜨겁고 짰다.","ok":false,"fix":"hot and salty","why":"looked 뒤에는 형용사가 보어로 와야 한다. 접속사 but이 앞의 tasty와 ‘hot and salty’를 나란히 이어 주므로 둘 다 형용사여야 한다. salt(소금)는 명사이므로 형용사 salty(짠)로 고쳐야 한다."},{"k":"ⓓ","en":"sleepy","ko":"졸린","ok":true,"fix":"","why":"‘feel + 형용사’는 ‘~한 느낌이 들다’라는 뜻이다. felt(원형 feel 느끼다) 뒤에 형용사 sleepy가 왔으므로 적절하다."},{"k":"ⓔ","en":"sunny","ko":"화창한","ok":true,"fix":"","why":"be동사 will be 뒤의 보어 자리이므로 형용사 sunny(화창한)는 적절하다."}],"vb":["looked → 원형 look ~해 보이다 (과거형 looked)","felt → 원형 feel 느끼다 (과거형 felt)","made → 원형 make 만들다 (과거형 made)"]},{"id":"g3-056","n":56,"u":2,"st":"다음 글의 밑줄 친 ⓐ~ⓔ 중 어법상 어색한 것은?","ty":"틀린 것 찾기","core":"look + 형용사 · seem to부정사 · 관용 표현","ans":[4],"kind":"seg","pol":"bad","body":"Dobin (16, Seoul)<br>My sister, a second-year student in high school, has a wonderful way to <b class=\"lb\">ⓐ</b><u>stay free from</u> stress. She feels a lot of stress from schoolwork, but my mother <b class=\"lb\">ⓑ</b><u>seems to like</u> the situation <b class=\"lb\">ⓒ</b><u>for a good reason</u>. It is because cleaning is my sister's <b class=\"lb\">ⓓ</b><u>number-one way</u> to make life better! When she's stressed out, she cleans her room. She says, \"As I clean my room, I feel like I'm also relieving stress. When my room looks tidy, my life <b class=\"lb\">ⓔ</b><u>looks brightly</u>.\"","bko":"도빈 (16세, 서울)\n내 누나는 고등학교 2학년인데, 스트레스에서 벗어나 있는 멋진 방법을 가지고 있다. 누나는 학교 공부 때문에 스트레스를 많이 받지만, 어머니는 합당한 이유로 그 상황을 좋아하시는 것 같다. 그 이유는 청소가 누나가 삶을 더 낫게 만드는 최고의 방법이기 때문이다! 누나는 스트레스를 받으면 자기 방을 청소한다. 누나는 이렇게 말한다. \"방을 청소하면서 나는 스트레스도 풀리는 느낌이 들어. 방이 깔끔해 보이면 내 삶도 밝아 보여.\"","opts":["ⓐ","ⓑ","ⓒ","ⓓ","ⓔ"],"segs":[{"k":"ⓐ","en":"stay free from","ko":"~에서 벗어난 상태로 있다","ok":true,"fix":"","why":"‘stay free from ~’은 ‘~로부터 자유로운 상태로 있다’라는 뜻의 표현이다. stay(원형 stay 머무르다) 뒤에 형용사 free가 보어로 왔으므로 적절하다."},{"k":"ⓑ","en":"seems to like","ko":"좋아하는 것 같다","ok":true,"fix":"","why":"‘seem + to부정사(to + 동사원형)’는 ‘~하는 것처럼 보이다’라는 뜻이다. 주어 my mother가 3인칭 단수이므로 seems(원형 seem ~처럼 보이다)로 맞췄다. 따라서 적절하다."},{"k":"ⓒ","en":"for a good reason","ko":"합당한 이유로","ok":true,"fix":"","why":"‘for a good reason’은 ‘그럴 만한 이유로, 합당한 이유로’라는 뜻의 표현이다."},{"k":"ⓓ","en":"number-one way","ko":"최고의 방법","ok":true,"fix":"","why":"number-one은 ‘제일가는, 최고의’라는 뜻의 형용사로 명사 way를 꾸민다. 따라서 적절하다."},{"k":"ⓔ","en":"looks brightly","ko":"밝아 보인다.","ok":false,"fix":"looks bright","why":"looks(원형 look ~해 보이다)는 뒤에 형용사를 보어로 써서 ‘~해 보이다’라는 뜻을 나타낸다. 부사 brightly(밝게)는 보어 자리에 올 수 없으므로 형용사 bright(밝은)로 고쳐야 한다."}],"vb":["looks → 원형 look ~해 보이다 (3인칭 단수 현재형 looks)","seems → 원형 seem ~처럼 보이다 (3인칭 단수 현재형 seems)","cleans → 원형 clean 청소하다 (3인칭 단수 현재형 cleans)"]},{"id":"g3-057","n":57,"u":2,"st":"다음 글의 괄호 (A), (B), (C) 안에서 어법에 맞는 말을 골라 짝지은 것은?","ty":"조합 고르기","core":"가주어 It · 부분 표현의 수일치 · 비교급 강조 even","ans":[4],"kind":"abc","body":"Where have all the honey bees gone? (A)[It / That] is really hard to see them these days. The bees are disappearing! About a third of the bee population (B)[die / dies] every year. This is bad news for bees, but it’s (C)[even / very] worse news for people.","bko":"꿀벌들은 모두 어디로 갔을까? 요즘은 꿀벌을 보기가 정말 어렵다. 꿀벌들이 사라지고 있다! 꿀벌 개체 수의 약 3분의 1이 해마다 죽는다. 이것은 벌에게 나쁜 소식이지만, 사람에게는 훨씬 더 나쁜 소식이다.","opts":[{"t":"It die even","ko":"(A) It 그것 / (B) die 죽다(원형) / (C) even 훨씬","fix":"","why":""},{"t":"That die even","ko":"(A) That 저것 / (B) die 죽다(원형) / (C) even 훨씬","fix":"","why":""},{"t":"It dies very","ko":"(A) It 그것 / (B) dies 죽다 / (C) very 매우","fix":"","why":""},{"t":"That dies very","ko":"(A) That 저것 / (B) dies 죽다 / (C) very 매우","fix":"","why":""},{"t":"It dies even","ko":"(A) It 그것 / (B) dies 죽다 / (C) even 훨씬","fix":"","why":""}],"blob":"(A) to see them이 ‘그들을 보는 것’이라는 진짜 주어(진주어)이고, 문장 앞에는 이를 대신하는 가짜 주어(가주어)가 필요하다. 가주어로는 It을 쓰며 that은 쓰지 않는다. (B) About a third of the bee population(꿀벌 개체 수의 약 3분의 1)에서 핵심 명사는 the bee population(단수)이다. 그러므로 동사도 단수형 dies(원형 die 죽다)로 써야 한다. (C) worse는 bad의 비교급이다. 비교급을 꾸며 ‘훨씬’이라는 뜻을 더하는 말은 even, much, a lot, still이고, very(매우)는 쓰지 않는다. 따라서 even이 알맞다. 정답은 It – dies – even이다.","vb":["dies → 원형 die 죽다 (3인칭 단수 현재형 dies)","gone → 원형 go 가다 (과거분사 gone)"]},{"id":"g3-058","n":58,"u":2,"st":"다음 글의 밑줄 친 부분 중 어법상 어색한 것은?","ty":"틀린 것 찾기","core":"목적보어 자리의 형용사 · 형용사적 to부정사 · 접속사 that·if","ans":[4],"kind":"seg","pol":"bad","body":"After I came back, I took part in a photo contest with the pictures I took in Iceland. Surprisingly, I won first prize, and this gave me a chance <b class=\"lb\">ⓐ</b><u>to think</u> about my life. I realized <b class=\"lb\">ⓑ</b><u>that</u> taking pictures made me glad. Suddenly, I wanted to become a good photographer, so I stared to learn more about photography. After years of trial and error, I got <b class=\"lb\">ⓒ</b><u>better</u>, and I began to do some part-tie work as a photographer. Then one day, I made a decision. I quit my job and decided to take pictures for a living. I wasn’t sure <b class=\"lb\">ⓓ</b><u>if</u> I could succeed, but I decided to try. I really wanted to do something that made me <b class=\"lb\">ⓔ</b><u>happily</u>. Now, I’m a professional photographer, and I’m satisfied.","bko":"돌아온 뒤, 나는 아이슬란드에서 찍은 사진들로 사진 대회에 참가했다. 놀랍게도 나는 1등을 했고, 이것은 내 삶에 대해 생각해 볼 기회를 주었다. 나는 사진을 찍는 것이 나를 기쁘게 한다는 것을 깨달았다. 갑자기 나는 훌륭한 사진작가가 되고 싶어졌고, 그래서 사진에 대해 더 배우기 시작했다. 수년간의 시행착오 끝에 나는 더 나아졌고, 사진작가로서 아르바이트 일을 하기 시작했다. 그러던 어느 날, 나는 결심을 했다. 나는 직장을 그만두고 사진을 찍어 먹고살기로 결정했다. 내가 성공할 수 있을지 확신이 없었지만 시도해 보기로 했다. 나는 정말로 나를 행복하게 만드는 일을 하고 싶었다. 이제 나는 전문 사진작가이고, 만족한다.","opts":["ⓐ","ⓑ","ⓒ","ⓓ","ⓔ"],"segs":[{"k":"ⓐ","en":"to think","ko":"생각할","ok":true,"fix":"","why":"to think(원형 think 생각하다)는 앞의 명사 a chance(기회)를 꾸며 ‘생각할 기회’라는 뜻을 나타내는 형용사 역할의 to부정사이다. 따라서 적절하다."},{"k":"ⓑ","en":"that","ko":"~라는 것","ok":true,"fix":"","why":"realized(원형 realize 깨닫다)의 목적어로 ‘~라는 것’을 나타내는 절(주어 + 동사가 있는 덩어리)을 이끄는 접속사 that은 적절하다."},{"k":"ⓒ","en":"better","ko":"더 나은","ok":true,"fix":"","why":"‘get better’는 ‘더 좋아지다’라는 뜻이다. got(원형 get ~해지다) 뒤에 형용사 good의 비교급 better가 왔으므로 적절하다."},{"k":"ⓓ","en":"if","ko":"~인지 아닌지","ok":true,"fix":"","why":"sure 뒤에서 ‘~인지 아닌지’라는 뜻의 절을 이끄는 접속사 if는 적절하다."},{"k":"ⓔ","en":"happily","ko":"행복하게","ok":false,"fix":"happy","why":"made(원형 make 만들다)는 ‘make + 목적어(me) + 목적보어’ 꼴로 ‘~을 -하게 만들다’라는 뜻이다. 동사를 꾸미는 말이 아니라 목적어 me의 상태를 설명하는 목적보어이므로 형용사 happy(행복한)로 고쳐야 한다. 부사 happily는 쓸 수 없다."}],"vb":["took → 원형 take 찍다 (take part in: 참가하다) (과거형 took)","won → 원형 win 이기다 (과거형 won)","made → 원형 make 만들다 (과거형 made)","got → 원형 get ~해지다 (과거형 got)"]},{"id":"g3-059","n":59,"u":2,"st":"다음 중 어법상 옳은 것은?","ty":"옳은 것 고르기","core":"사역동사 have · It ~ that 강조구문 · the 비교급 ~, the 비교급 · 물질명사","ans":[4],"kind":"sent","pol":"good","opts":[{"t":"Ms. White has us on time for every class.","ko":"화이트 선생님은 매 수업마다 우리를 제시간에 (있게) 하신다.","ok":false,"fix":"Ms. White has us be on time for every class.","why":"has는 ‘~에게 시키다’라는 뜻의 사역동사이다. ‘시키다’의 목적어 us 뒤에는 목적보어로 동사원형이 와야 하는데 ‘제시간에 있다’는 뜻을 나타내려면 be가 필요하다. be가 빠졌으므로 has us be on time으로 고쳐야 한다. has(원형 have 시키다)."},{"t":"I had bring my sister my gym uniform.","ko":"나는 내 여동생에게 내 체육복을 가져다주게 했다.","ok":false,"fix":"I had my sister bring my gym uniform.","why":"had bring이라는 동사 형태는 없다. ‘사역동사 had + 목적어(my sister) + 목적보어(동사원형 bring)’ 순서로 써야 한다. 또는 had brought(과거완료, had + p.p.)로 고칠 수도 있다. bring(원형 bring 가져오다)."},{"t":"It was Tom that I met her in front of the bank.","ko":"내가 은행 앞에서 그녀를 만난 것은 Tom이었다.","ok":false,"fix":"It was Tom that I met in front of the bank.","why":"‘It is/was + 강조할 말 + that + 나머지’는 특정 말을 강조하는 강조구문이다. I met Tom in front of the bank.에서 Tom을 강조한 문장이므로 met(원형 meet 만나다)의 목적어가 이미 Tom이다. 그러므로 her는 필요 없다."},{"t":"The older we grow, the wise we become.","ko":"우리는 나이가 들수록 더 현명해진다.","ok":false,"fix":"The older we grow, the wiser we become.","why":"‘the 비교급 + 주어 + 동사, the 비교급 + 주어 + 동사’는 ‘~할수록 더 -하다’라는 뜻이다. 뒤에도 비교급이 필요하므로 wise는 wiser로 고쳐야 한다. grow(원형 grow 자라다), become(원형 become ~이 되다)."},{"t":"Ann drank two glasses of water since she was thirsty.","ko":"Ann은 목이 말랐기 때문에 물을 두 잔 마셨다.","ok":true,"fix":"","why":"water(물)는 셀 수 없는 물질명사라서 단독으로 복수형(waters)을 쓸 수 없고, a glass of water, two glasses of water 처럼 컵의 수를 세어 나타낸다. since는 여기서 ‘~이기 때문에’라는 뜻의 접속사이다. drank(원형 drink 마시다), was(원형 be ~이다)."}],"vb":["drank → 원형 drink 마시다 (과거형 drank)","met → 원형 meet 만나다 (과거형 met)"]},{"id":"g3-060","n":60,"u":2,"st":"다음 글의 밑줄 친 ⓐ~ⓔ 중, 어법상 어색한 것은?","ty":"틀린 것 찾기","core":"비교급 강조 much·even·a lot · 사역동사 let · so ~ that","ans":[4],"kind":"seg","pol":"bad","body":"The manager <b class=\"lb\">ⓐ</b><u>let us paint</u> anything we wanted. We decided to paint something cute because the wall was near an elementary school. We <b class=\"lb\">ⓑ</b><u>divided into three groups</u> and began painting. I was in the group with Minsu and Jiwon. I chose my spot and <b class=\"lb\">ⓒ</b><u>started to paint</u> my favorite movie character. Minsu painted some flowers and Jiwon did some background drawings.<br>Our club painted for about five hours. Minsu was very proud of his flower painting. He said, \"My flower is <b class=\"lb\">ⓓ</b><u>so real that</u> a bee landed on it.\" I said, \"Drawing on a wall was <b class=\"lb\">ⓔ</b><u>very harder than</u> a drawing on paper.\"","bko":"관리자는 우리가 원하는 것은 무엇이든 그리게 해 주었다. 벽이 초등학교 근처에 있었기 때문에 우리는 귀여운 것을 그리기로 했다. 우리는 세 모둠으로 나뉘어 그림을 그리기 시작했다. 나는 민수, 지원이와 같은 모둠이었다. 나는 내 자리를 골라 내가 가장 좋아하는 영화 캐릭터를 그리기 시작했다. 민수는 꽃을 몇 송이 그렸고 지원이는 배경 그림을 그렸다.\n우리 동아리는 약 다섯 시간 동안 그림을 그렸다. 민수는 자신의 꽃 그림이 매우 자랑스러웠다. 그는 말했다. \"내 꽃은 너무 진짜 같아서 벌이 그 위에 앉았어.\" 나는 말했다. \"벽에 그리는 것은 종이에 그리는 것보다 훨씬 더 어려웠어.\"","opts":["ⓐ","ⓑ","ⓒ","ⓓ","ⓔ"],"segs":[{"k":"ⓐ","en":"let us paint","ko":"우리가 그리게 해 주었다","ok":true,"fix":"","why":"let은 ‘~하게 해 주다’라는 뜻의 사역동사(시키거나 허락하는 동사)이다. ‘let + 목적어(us) + 목적보어’에서 목적어와 목적보어가 능동 관계(우리가 그린다)이면 목적보어는 동사원형 paint(원형 paint 그리다)를 쓴다. 따라서 적절하다."},{"k":"ⓑ","en":"divided into three groups","ko":"세 모둠으로 나뉘었다","ok":true,"fix":"","why":"divided(원형 divide 나누다)는 여기서 ‘나뉘다’라는 뜻으로 쓰였고, 전치사 into는 변화의 결과를 나타내어 ‘~로’라는 뜻이다. 따라서 적절하다."},{"k":"ⓒ","en":"started to paint","ko":"그리기 시작했다","ok":true,"fix":"","why":"‘start + to부정사/동명사’는 ‘~하기 시작하다’라는 뜻이다. started(원형 start 시작하다) 뒤에 to paint가 왔으므로 적절하다."},{"k":"ⓓ","en":"so real that","ko":"너무 진짜 같아서","ok":true,"fix":"","why":"‘so ~ that …’은 ‘너무 ~해서 …하다’라는 뜻이다. that은 결과를 이끄는 접속사이므로 적절하다."},{"k":"ⓔ","en":"very harder than","ko":"훨씬 더 어려운","ok":false,"fix":"much harder than","why":"비교급(harder)을 꾸며 ‘훨씬’이라는 뜻을 만들려면 much, even, a lot, still, by far를 쓴다. very는 원급(그냥 형용사·부사 모양)이나 현재분사를 꾸밀 때 쓰므로 비교급 앞에 쓸 수 없다. 따라서 very harder than은 much harder than(또는 even / a lot harder than)이 적절하다."}],"vb":["divided → 원형 divide 나누다 (과거형 divided)","started → 원형 start 시작하다 (과거형 started)","landed → 원형 land 내려앉다 (과거형 landed)"]},{"id":"g3-061","n":61,"u":2,"st":"다음 밑줄 친 부분이 어법상 옳은 것은?","ty":"옳은 것 고르기","core":"감정 분사형 형용사 -ing / -ed","ans":[2],"kind":"sent","pol":"good","opts":[{"t":"Are you exciting for your new job?","ko":"너는 새 직장 때문에 신이 나 있니? (밑줄: exciting)","ok":false,"fix":"Are you excited for your new job?","why":"주어 you가 ‘흥분하는’(감정을 느끼는) 사람이므로 과거분사 excited(신이 난)를 써야 한다. exciting은 ‘흥미진진하게 하는’이라는 뜻이다."},{"t":"My exam results were a little disappointed.","ko":"내 시험 결과는 조금 실망스러웠다. (밑줄: disappointed)","ok":false,"fix":"My exam results were a little disappointing.","why":"시험 결과가 ‘실망을 주는’ 것이므로 현재분사 disappointing(실망스러운)이 알맞다. disappointed는 ‘실망한(사람)’이라는 뜻이다. were(원형 be ~이다)."},{"t":"The metro can be confusing the first time you use it.","ko":"지하철은 처음 이용할 때 헷갈릴 수 있다. (밑줄: confusing)","ok":true,"fix":"","why":"지하철이 ‘혼란스럽게 하는’ 것이므로 현재분사 confusing(헷갈리게 하는)은 적절하다. use(원형 use 이용하다)."},{"t":"What was the last interested TV show you watched?","ko":"네가 마지막으로 본 흥미로운 TV 쇼는 무엇이었니? (밑줄: interested)","ok":false,"fix":"What was the last interesting TV show you watched?","why":"TV 쇼가 ‘흥미를 주는’ 것이므로 현재분사 interesting(흥미로운)이 알맞다. interested는 ‘관심을 가진(사람)’이라는 뜻이다. watched(원형 watch 보다)."},{"t":"What music do you listen to if you feel depressing?","ko":"기분이 우울할 때 너는 어떤 음악을 듣니? (밑줄: depressing)","ok":false,"fix":"What music do you listen to if you feel depressed?","why":"주어 you가 ‘우울함을 느끼는’ 사람이므로 과거분사 depressed(우울한)가 알맞다. depressing은 ‘우울하게 만드는’이라는 뜻이다. feel(원형 feel 느끼다)."}],"vb":["use → 원형 use 이용하다","watched → 원형 watch 보다 (과거형 watched)","feel → 원형 feel 느끼다","listen → 원형 listen 듣다"]},{"id":"g3-062","n":62,"u":2,"st":"다음 글의 밑줄 친 ⓐ~ⓔ 중 어법상 옳지 않은 것은?","ty":"틀린 것 찾기","core":"look + 형용사 · 사역동사 have · so ~ that","ans":[3],"kind":"seg","pol":"bad","body":"I <b class=\"lb\">ⓐ</b><u>volunteered</u> at Dream Library. I read English books to children. I tried to read like a voice actor. The volunteer manager had me <b class=\"lb\">ⓑ</b><u>arrange</u> the books on the shelves. The books were so <b class=\"lb\">ⓒ</b><u>heavy</u> that I had to take a break every 30 minutes. After I finished, the shelves looked very <b class=\"lb\">ⓓ</b><u>neatly</u>. I felt very proud. It was a fun and <b class=\"lb\">ⓔ</b><u>rewarding</u> experience.","bko":"나는 꿈 도서관에서 자원봉사를 했다. 나는 아이들에게 영어책을 읽어 주었다. 나는 성우처럼 읽으려고 노력했다. 자원봉사 관리자는 나에게 책장의 책들을 정리하게 했다. 책들이 너무 무거워서 나는 30분마다 쉬어야 했다. 끝낸 뒤 책장들은 매우 깔끔해 보였다. 나는 매우 뿌듯했다. 재미있고 보람 있는 경험이었다.","opts":["ⓐ","ⓑ","ⓒ","ⓓ","ⓔ"],"segs":[{"k":"ⓐ","en":"volunteered","ko":"자원봉사를 했다","ok":true,"fix":"","why":"과거에 있었던 일을 말하므로 과거형 volunteered(원형 volunteer 자원봉사하다)를 쓴 것은 적절하다."},{"k":"ⓑ","en":"arrange","ko":"정리하다","ok":true,"fix":"","why":"had는 ‘~에게 시키다’라는 뜻의 사역동사이다. ‘had + 목적어(me) + 목적보어’에서 목적어와 목적보어가 능동 관계(내가 정리한다)이면 목적보어는 동사원형 arrange(원형 arrange 정리하다)를 쓴다. 따라서 적절하다."},{"k":"ⓒ","en":"heavy","ko":"무거운","ok":true,"fix":"","why":"동사 were(원형 be ~이다)의 보어(주어를 설명하는 말)로 형용사 heavy(무거운)가 왔으므로 적절하다. ‘so ~ that …’은 ‘너무 ~해서 …하다’라는 뜻이다."},{"k":"ⓓ","en":"neatly","ko":"깔끔하게","ok":false,"fix":"neat","why":"‘look + 형용사’는 ‘~해 보이다’라는 뜻이다. looked(원형 look ~해 보이다) 뒤에는 보어로 형용사가 와야 하므로 부사 neatly(깔끔하게)는 알맞지 않고 형용사 neat(깔끔한)로 고쳐야 한다."},{"k":"ⓔ","en":"rewarding","ko":"보람 있는","ok":true,"fix":"","why":"뒤의 명사 experience(경험)를 꾸미는 말이다. 경험이 ‘보람을 주는’ 것이므로 능동의 뜻을 가진 현재분사 rewarding(보람 있는)은 적절하다."}],"vb":["volunteered → 원형 volunteer 자원봉사하다 (과거형 volunteered)","tried → 원형 try 노력하다 (과거형 tried)","looked → 원형 look ~해 보이다 (과거형 looked)","felt → 원형 feel 느끼다 (과거형 felt)"]},{"id":"g3-063","n":63,"u":2,"st":"다음 주어진 우리말과 같도록 괄호 안에서 한 단어를 고르시오.","ty":"괄호 고르기","core":"become + 형용사 보어 · 부사는 보어가 될 수 없다","ans":[0],"kind":"sent","pol":"good","body":"Brokk became [angry / angrily] and accepted the challenge.","bko":"Brokk는 화가 나서 그 도전을 받아들였다.","opts":[{"t":"angry","ko":"화난","ok":true,"fix":"","why":"become(원형 become ~이 되다)은 ‘~이 되다’라는 뜻으로 뒤에 보어(주어를 설명하는 말)가 필요한 동사이다. 보어 자리에는 형용사나 명사가 오므로 형용사 angry(화난)가 알맞다."},{"t":"angrily","ko":"화나서, 화난 듯이","ok":false,"fix":"angry","why":"angrily는 부사이다. 부사는 문장 성분 중 보어가 될 수 없으므로 become 뒤에 쓸 수 없고 형용사 angry로 고쳐야 한다. accepted(원형 accept 받아들이다)."}],"vb":["became → 원형 become ~이 되다 (과거형 became)","accepted → 원형 accept 받아들이다 (과거형 accepted)"]},{"id":"g3-066","n":66,"u":2,"st":"다음 글의 밑줄 친 ⓐ~ⓔ 중 어법상 옳은 것은?","ty":"옳은 것 고르기","core":"5형식 목적보어 형용사 · 현재완료 의문문 · 대동사 · look forward to · 분사구문","ans":[2],"kind":"seg","pol":"good","body":"Scene 3: In the Frog Prince's house<br>(Prince runs in, smiling.)<br>Princess: <b class=\"lb\">ⓐ</b><u>Where has you been?</u> I've been worried. Your clothes are a mess.<br>Prince: (Looking at Princess) <b class=\"lb\">ⓑ</b><u>You believed me when no one else in the world do.</u> You loved me even when I was a frog. From now on, I will make you happier.<br>Princess: I'm glad to hear that. <b class=\"lb\">ⓒ</b><u>I'll make you much happier.</u><br>Prince: Great! <b class=\"lb\">ⓓ</b><u>I'm looking forward at our bright future.</u> Ha-ha ....<br><b class=\"lb\">ⓔ</b><u>(They run to the pond together, jump hand in hand.)</u>","bko":"장면 3: 개구리 왕자의 집에서\n(왕자가 웃으며 뛰어 들어온다.)\n공주: 어디 있었어요? 걱정했어요. 옷이 엉망이에요.\n왕자: (공주를 바라보며) 당신은 세상의 다른 누구도 믿지 않을 때 나를 믿어 주었소. 내가 개구리였을 때도 나를 사랑해 주었소. 지금부터 나는 당신을 더 행복하게 해 주겠소.\n공주: 그 말을 들으니 기뻐요. 저도 당신을 훨씬 더 행복하게 해 드릴게요.\n왕자: 좋소! 우리의 밝은 미래가 몹시 기대되오. 하하….\n그리고 두 사람이 함께 연못으로 달려가 손에 손을 잡고 뛰어든다.","segs":[{"k":"ⓐ","en":"Where has you been?","ko":"어디 있었니?","ok":false,"fix":"Where have you been?","why":"주어 you(너)는 복수 취급하는 말이라 현재완료(have + 과거분사, ~해 왔다)에서 has가 아니라 have를 써야 한다. 따라서 has는 have가 적절하다."},{"k":"ⓑ","en":"You believed me when no one else in the world do.","ko":"세상 누구도 (믿지) 않을 때 너는 나를 믿었다.","ok":false,"fix":"You believed me when no one else in the world does.","why":"when절의 주어 no one else(다른 아무도 ~ 않다)는 단수로 취급하므로 동사도 단수동사로 맞춰야 한다. 따라서 do는 does가 적절하다. 이때 does는 앞의 believe me(나를 믿다)를 대신하는 대동사(앞에 나온 동사를 대신 받는 do)이다."},{"k":"ⓒ","en":"I'll make you much happier.","ko":"나는 너를 훨씬 더 행복하게 만들어 줄게.","ok":true,"fix":"","why":"make(만들다)는 ‘목적어(you)를 ~하게 만들다’라는 뜻으로 목적어 뒤에 목적보어(목적어가 어떤 상태인지 설명하는 말)가 온다. 목적보어 자리에는 형용사 happier(더 행복한)가 알맞고, much가 비교급을 강조(훨씬)한다. 따라서 make you much happier는 적절하다."},{"k":"ⓓ","en":"I'm looking forward at our bright future.","ko":"나는 우리의 밝은 미래를 학수고대하고 있다.","ok":false,"fix":"looking forward to our bright future.","why":"‘look forward to + 명사’는 ‘~을 학수고대하다(몹시 기다리다)’라는 뜻이다. 이때 to는 전치사이다. 따라서 at은 to가 적절하다."},{"k":"ⓔ","en":"(They run to the pond together, jump hand in hand.)","ko":"(그들은 함께 연못으로 달려가 손에 손을 잡고 뛰어든다.)","ok":false,"fix":"(They run to the pond together, jumping hand in hand.)","why":"접속사 없이 동사 run(달리다)과 jump(뛰다)를 나란히 쓸 수 없다. 동시에 일어나는 동작은 분사구문(접속사와 주어를 줄이고 -ing로 쓴 구)으로 나타내야 한다. ‘~하면서’라는 뜻의 동시동작이다. 따라서 jump는 jumping이 적절하다."}],"opts":["ⓐ","ⓑ","ⓒ","ⓓ","ⓔ"],"vb":["has → 원형 have 가지다 (have been: 있었다, 현재완료)","believed → 원형 believe 믿다 (과거형 believed)","do → 원형 do 하다 (대동사, 단수 주어 뒤에서는 does)","run → 원형 run 달리다","jump → 원형 jump 뛰다 (jumping 분사구문)"]},{"id":"g3-067","n":67,"u":2,"st":"다음 중 뜻이 서로 다른 하나를 고르면?","ty":"다른 것 찾기","core":"최상급 · 비교급을 이용한 최상급 표현 · 이중부정","ans":[4],"kind":"sent","pol":"bad","opts":[{"t":"She is the prettiest girl in the class.","ko":"그녀는 학급에서 가장 예쁜 소녀이다.","ok":true,"why":"pretty(예쁜)의 최상급(가장 ~한) prettiest에 the를 붙인 문장으로 ‘학급에서 가장 예쁘다’라는 뜻이다. 다른 보기들과 뜻이 같다.","fix":""},{"t":"She is the prettiest of all girls in the class.","ko":"그녀는 학급의 모든 소녀 중에서 가장 예쁘다.","ok":true,"why":"‘the + 최상급 + of all ~’도 ‘모든 ~ 중에서 가장 …하다’라는 뜻으로 ‘학급에서 가장 예쁘다’와 같다.","fix":""},{"t":"No other girl in the class is prettier than she.","ko":"학급의 어떤 다른 소녀도 그녀보다 더 예쁘지 않다.","ok":true,"why":"‘No other + 명사 + 비교급 + than ~’은 ‘어떤 다른 …도 ~보다 더 …하지 않다’라는 뜻이라서 결국 그녀가 가장 예쁘다는 말이 된다. 뜻이 같다.","fix":""},{"t":"She is prettier than any other girl in the class.","ko":"그녀는 학급의 어떤 다른 소녀보다 더 예쁘다.","ok":true,"why":"‘비교급 + than any other + 단수명사’는 ‘다른 어떤 ~보다 더 …하다’라는 뜻이라서 결국 가장 예쁘다는 말이 된다. 뜻이 같다.","fix":""},{"t":"No other girl in the class isn't as pretty as she.","ko":"학급의 어떤 다른 소녀도 그녀만큼 예쁘지 않지 않다. (즉 다른 소녀들도 모두 그녀만큼 예쁘다는 뜻이 되어 이상하다.)","ok":false,"why":"No(어떤 ~도 않다)와 isn’t(~이 아니다)가 함께 있어 부정이 두 번 겹쳤다(이중부정). 그러면 ‘모든 소녀가 그녀만큼 예쁘다’는 뜻이 되어 나머지 넷과 뜻이 달라진다. 따라서 isn’t는 is로 고쳐야 한다.","fix":"No other girl in the class is as pretty as she."}],"vb":["is → 원형 be 이다 (is, 3인칭 단수)"]},{"id":"g3-068","n":68,"u":2,"st":"다음 글의 밑줄 친 부분 중, 어법상 어색한 것은?","ty":"틀린 것 찾기","core":"부사가 동사 수식 · in detail · in a hurry · get + 과거분사 · by oneself","ans":[0],"kind":"seg","pol":"bad","body":"How did you do the marshmallow challenge?<br>Every team does the marshmallow challenge <b class=\"lb\">ⓐ</b><u>different.</u> Let's look at some examples. Which one do you like best?<br>Team A<br>We had many good ideas. We talked about each idea <b class=\"lb\">ⓑ</b><u>in detail.</u> It was not easy for us to choose the best idea. Suddenly the teacher said, \"Five minutes left.\" <b class=\"lb\">ⓒ</b><u>In a hurry,</u> we taped the sticks of spaghetti together. Then, we wrapped the string around them. The string <b class=\"lb\">ⓓ</b><u>got stuck</u> to the tape and it was a big mess. With one second left, I put the marshmallow on top!<br>Team B<br>We didn't spend much time on planning. All the members started building the tower right away. Our first tower looked like a tent. It wasn't very tall. We tried again. The next tower was tall but it couldn't stand <b class=\"lb\">ⓔ</b><u>by itself.</u> After many tries, it was possible for us to build a beautiful and tall tower. It looked like the Leaning Tower of Pisa. We finally made what we wanted!","bko":"여러분은 마시멜로 챌린지를 어떻게 했나요?\n모든 팀이 마시멜로 챌린지를 다르게 한다. 몇 가지 예를 살펴보자. 어느 것이 가장 마음에 드는가?\nA팀\n우리는 좋은 아이디어가 많았다. 우리는 각 아이디어에 대해 자세히 이야기했다. 가장 좋은 아이디어를 고르는 것은 우리에게 쉽지 않았다. 갑자기 선생님께서 “5분 남았어요.”라고 말씀하셨다. 서둘러서 우리는 스파게티 막대들을 테이프로 함께 붙였다. 그러고 나서 그 둘레에 끈을 감았다. 끈이 테이프에 붙어 버려서 크게 엉망이 되었다. 1초를 남기고 나는 마시멜로를 꼭대기에 올렸다!\nB팀\n우리는 계획을 세우는 데 많은 시간을 쓰지 않았다. 모든 팀원이 곧바로 탑을 짓기 시작했다. 우리의 첫 번째 탑은 텐트처럼 보였다. 그다지 높지 않았다. 우리는 다시 시도했다. 다음 탑은 높았지만 혼자서는 서 있을 수 없었다. 여러 번 시도한 끝에 우리는 아름답고 높은 탑을 지을 수 있었다. 그것은 피사의 사탑처럼 보였다. 우리는 마침내 우리가 원하던 것을 만들어 냈다!","segs":[{"k":"ⓐ","en":"different.","ko":"다르게.","ok":false,"fix":"differently.","why":"동사 does(하다)를 꾸며 ‘어떻게 하는지’를 말할 때는 부사를 써야 한다. different(다른)는 형용사이다. 따라서 different는 부사 differently(다르게)가 적절하다."},{"k":"ⓑ","en":"in detail.","ko":"자세히.","ok":true,"fix":"","why":"in detail은 ‘상세히, 자세히’라는 뜻의 표현이다. 따라서 적절하다."},{"k":"ⓒ","en":"In a hurry,","ko":"서둘러서,","ok":true,"fix":"","why":"in a hurry는 ‘서둘러서’라는 뜻의 표현이다. 따라서 적절하다."},{"k":"ⓓ","en":"got stuck","ko":"붙어 버렸다","ok":true,"fix":"","why":"‘get + 과거분사(p.p., 동사의 세 번째 모양)’는 ‘~하게 되다’라는 수동의 뜻이다. stuck(붙은)은 stick(원형 stick 고정하다, 붙이다)의 과거분사이다. 따라서 got stuck은 적절하다."},{"k":"ⓔ","en":"by itself.","ko":"저절로, 혼자서.","ok":true,"fix":"","why":"by oneself는 ‘스스로, 혼자서’라는 뜻이다. itself(그것 자신)는 the next tower(다음 탑)를 가리키는 재귀대명사(~ 자신을 나타내는 말)이다. 따라서 적절하다."}],"opts":["ⓐ","ⓑ","ⓒ","ⓓ","ⓔ"],"vb":["got → 원형 get 되다 (과거형 got, got stuck 붙어 버렸다)","stuck → 원형 stick 붙이다 (과거분사 stuck)"]},{"id":"g3-069","n":69,"u":2,"st":"다음 글의 밑줄 친 ⓐ~ⓔ 중 어법상 옳지 않은 것은?","ty":"틀린 것 찾기","core":"지각동사 + 목적어 + 동사원형 · 부사 around · 대명사 수 일치 · nearby","ans":[3],"kind":"seg","pol":"bad","body":"You have probably seen a bird <b class=\"lb\">ⓐ</b><u>fly</u> down to the sea to catch a fish. But have you ever seen a fish jump out of the water to catch a bird? Well, birds have to be careful when a giant trevally is <b class=\"lb\">ⓑ</b><u>around.</u> This fish can grow up to 170cm and 80kg. But don’t let its size fool you. This fish is <b class=\"lb\">ⓒ</b><u>quick</u> and smart. It can spot a flying bird and calculate <b class=\"lb\">ⓓ</b><u>their</u> speed and distance. When the bird flies <b class=\"lb\">ⓔ</b><u>nearby,</u> the giant trevally jumps out of the water and catches it.","bko":"여러분은 아마도 새가 물고기를 잡으려고 바다로 날아 내려오는 것을 본 적이 있을 것이다. 하지만 물고기가 새를 잡으려고 물 밖으로 뛰어오르는 것을 본 적이 있는가? 글쎄, 새들은 자이언트 트레발리(물고기 이름)가 근처에 있을 때는 조심해야 한다. 이 물고기는 170cm, 80kg까지 자랄 수 있다. 하지만 그 크기에 속지 마라. 이 물고기는 빠르고 영리하다. 날아가는 새를 발견하고 그 새의 속도와 거리를 계산할 수 있다. 새가 근처에서 날면, 자이언트 트레발리는 물 밖으로 뛰어올라 그 새를 잡는다.","segs":[{"k":"ⓐ","en":"fly","ko":"날아 (내려오는 것)","ok":true,"fix":"","why":"‘지각동사(see, 보고 듣고 느끼는 동사) + 목적어(a bird) + 목적보어’에서 목적어와 목적보어가 능동 관계(새가 날다)이면 목적보어는 동사원형이나 현재분사로 쓴다. 따라서 fly(원형 fly 날다)는 적절하다."},{"k":"ⓑ","en":"around.","ko":"근처에.","ok":true,"fix":"","why":"동사 is는 ‘있다’라는 뜻이고, around(주변에)는 장소를 나타내는 부사이다. 따라서 is around(근처에 있다)는 적절하다."},{"k":"ⓒ","en":"quick","ko":"빠른","ok":true,"fix":"","why":"be동사 is(이다) 뒤에는 보어(주어를 설명하는 말)가 와야 하는데, 보어 자리에는 형용사가 알맞다. 따라서 형용사 quick(빠른)은 적절하다."},{"k":"ⓓ","en":"their","ko":"그것들의","ok":false,"fix":"its","why":"their(그들의)가 가리키는 것은 a flying bird(날아가는 새 한 마리)로 단수이다. 따라서 복수 소유격 their는 단수 소유격 its(그것의)가 적절하다."},{"k":"ⓔ","en":"nearby,","ko":"근처에서,","ok":true,"fix":"","why":"nearby는 ‘가까이에’라는 뜻의 부사로 flies(날다)를 꾸며 ‘새가 근처에서 날 때’라는 뜻이 된다. 따라서 적절하다."}],"opts":["ⓐ","ⓑ","ⓒ","ⓓ","ⓔ"],"vb":["seen → 원형 see 보다 (과거분사 seen, 현재완료)","fly → 원형 fly 날다","jump → 원형 jump 뛰어오르다","grow → 원형 grow 자라다","spot → 원형 spot 발견하다","calculate → 원형 calculate 계산하다"]},{"id":"g3-070","n":70,"u":2,"st":"다음 중 어법상 어색한 문장은? (정답 2개)","ty":"틀린 것 찾기","core":"tell + 목적어 + to부정사 · the 비교급 ~, the 비교급 ~ (easy의 비교급 easier)","ans":[3,4],"kind":"sent","pol":"bad","opts":[{"t":"I quit my job and decided to take pictures for a living.","ko":"나는 직장을 그만두고 생계를 위해 사진을 찍기로 결심했다.","ok":true,"why":"등위접속사(같은 종류를 이어 주는 말) and가 두 동사 quit과 decided를 같은 모양(과거형)으로 이어 주고 있다. quit은 quit-quit-quit으로 변하므로 과거형도 quit이다. 따라서 올바른 문장이다.","fix":""},{"t":"Having a happy brain will bring you happy results.","ko":"행복한 뇌를 가지는 것은 너에게 행복한 결과를 가져다줄 것이다.","ok":true,"why":"Having a happy brain(행복한 뇌를 가지는 것)은 동명사(동사 + -ing, ~하는 것) 주어이다. ‘bring + 간접목적어(you) + 직접목적어(happy results)’는 ‘~에게 -을 가져다주다’라는 뜻이다. 따라서 올바른 문장이다.","fix":""},{"t":"Negative thoughts are so harmful that they can damage your brain.","ko":"부정적인 생각은 매우 해로워서 너의 뇌를 손상시킬 수 있다.","ok":true,"why":"‘so + 형용사 + that ~’은 ‘매우 ~해서 …하다’라는 뜻이고, that은 결과를 나타내는 접속사이다. 따라서 올바른 문장이다.","fix":""},{"t":"Minsu tells Bora to talking with their math teacher, Mr. Lee.","ko":"민수는 보라에게 그들의 수학 선생님인 이 선생님과 이야기하라고 말한다.","ok":false,"why":"‘tell + 목적어(Bora) + to부정사’는 ‘~에게 …하라고 말하다’라는 뜻이다. to 뒤에는 동사원형이 와야 하므로 talking은 talk가 적절하다.","fix":"Minsu tells Bora to talk with their math teacher, Mr. Lee."},{"t":"The more you try to have positive thoughts, the more easy it will be for you to concentrate.","ko":"긍정적인 생각을 하려고 노력할수록 집중하기가 더 쉬워질 것이다.","ok":false,"why":"‘the + 비교급 ~, the + 비교급 ~’은 ‘~할수록 더 …하다’라는 뜻이다. easy(쉬운)의 비교급은 more easy가 아니라 easier(더 쉬운)이므로 the more easy는 the easier로 고쳐야 한다.","fix":"The more you try to have positive thoughts, the easier it will be for you to concentrate."}],"vb":["quit → 원형 quit 그만두다 (quit-quit-quit)","decided → 원형 decide 결심하다","tells → 원형 tell 말하다","talking → 원형 talk 이야기하다 (to 뒤에는 동사원형)","bring → 원형 bring 가져다주다","damage → 원형 damage 손상시키다"]},{"id":"g3-071","n":71,"u":2,"st":"다음 글의 밑줄 친 ⓐ~ⓔ 중 어법상 어색한 것은?","ty":"틀린 것 찾기","core":"원급 비교 as ~ as · 주격 관계대명사 · Here + be동사 + 주어","ans":[3],"kind":"seg","pol":"bad","body":"In sports, only the players get a trophy or medal, but they don't win <b class=\"lb\">ⓐ</b><u>on their own.</u> There are people <b class=\"lb\">ⓑ</b><u>who</u> help the players. These people are often hidden and don't get <b class=\"lb\">ⓒ</b><u>attention.</u> However, they are <b class=\"lb\">ⓓ</b><u>as most important as</u> the players. <b class=\"lb\">ⓔ</b><u>Here are</u> some examples.","bko":"스포츠에서는 선수들만 트로피나 메달을 받지만, 그들은 혼자 힘으로 이기는 것이 아니다. 선수들을 돕는 사람들이 있다. 이 사람들은 흔히 눈에 띄지 않고 주목을 받지 못한다. 그러나 그들은 선수들만큼 중요하다. 여기 몇 가지 예가 있다.","segs":[{"k":"ⓐ","en":"on their own.","ko":"그들 스스로, 혼자 힘으로.","ok":true,"fix":"","why":"on one’s own은 ‘스스로, 혼자 힘으로’라는 뜻이다. their가 가리키는 것은 the players(선수들)이다. 따라서 적절하다."},{"k":"ⓑ","en":"who","ko":"(~하는) 사람들","ok":true,"fix":"","why":"뒤의 동사 help(돕다)의 주어 역할을 하면서 앞뒤 말을 이어 주는 주격 관계대명사(앞의 명사를 꾸미는 절을 이끄는 말)가 필요하다. 앞의 people이 사람이므로 who가 적절하다."},{"k":"ⓒ","en":"attention.","ko":"주목.","ok":true,"fix":"","why":"get(받다)은 목적어가 필요한 동사인데, 그 목적어로 attention(주목)이 쓰였다. 따라서 적절하다."},{"k":"ⓓ","en":"as most important as","ko":"가장 중요한 만큼","ok":false,"fix":"as important as","why":"‘as + 형용사나 부사의 원래 모양(원급) + as ~’는 ‘~만큼 …한’이라는 뜻이다. 따라서 most important는 important가 적절하다."},{"k":"ⓔ","en":"Here are","ko":"여기 ~가 있다","ok":true,"fix":"","why":"‘Here + be동사 + 주어’는 ‘여기 ~가 있다’라는 뜻이다. 주어 some examples(몇 가지 예)가 복수이므로 복수동사 are가 알맞다. 따라서 적절하다."}],"opts":["ⓐ","ⓑ","ⓒ","ⓓ","ⓔ"],"vb":["get → 원형 get 받다","win → 원형 win 이기다","help → 원형 help 돕다"]},{"id":"g3-073","n":73,"u":2,"st":"다음 글의 밑줄 친 부분 중, 어법상 어색한 것은?","ty":"틀린 것 찾기","core":"감정을 일으키는 현재분사 pleasing · such a + 명사 · one of the + 복수명사 · that's how","ans":[1],"kind":"seg","pol":"bad","body":"Have you heard of the expression, \"Art Imitates nature?\" Many artists get their ideas and inspirations from the world around them. <b class=\"lb\">ⓐ</b><u>This is because the natural world is a beautiful place.</u> <b class=\"lb\">ⓑ</b><u>The shapes in nature are very pleased to the eye.</u> For example, look at the egg on the left. Isn't it beautiful? It is and delicate, yet strong enough to protect its contents. can you imagine a building that looks like an egg? <b class=\"lb\">ⓒ</b><u>Such a building actually exists in London.</u><br>Nature has inspired many architects around the world. This is the Sagrada Familia in Spain. <b class=\"lb\">ⓓ</b><u>It is one of the most famous churches in the world.</u> Look at the beautiful tall columns inside the church. They look like trees, don't they? The famous architect, Antoni Gaudi, used the shape of trees in the Sagrada Familia. <b class=\"lb\">ⓔ</b><u>That's how he brought the beauty of nature indoors.</u>","bko":"“예술은 자연을 모방한다”라는 표현을 들어 본 적이 있는가? 많은 예술가들은 자신을 둘러싼 세상에서 아이디어와 영감을 얻는다. 이것은 자연 세계가 아름다운 곳이기 때문이다. 자연 속의 모양들은 눈을 매우 즐겁게 해 준다. 예를 들어 왼쪽의 달걀을 보라. 아름답지 않은가? 그것은 (매끈하고) 섬세하면서도 내용물을 보호할 만큼 충분히 튼튼하다. 달걀처럼 생긴 건물을 상상할 수 있는가? 그런 건물이 실제로 런던에 있다.\n자연은 전 세계의 많은 건축가들에게 영감을 주었다. 이것은 스페인의 사그라다 파밀리아이다. 그것은 세계에서 가장 유명한 성당 중 하나이다. 성당 안의 아름답고 높은 기둥들을 보라. 그것들은 나무처럼 보이지, 그렇지 않은가? 유명한 건축가 안토니 가우디는 사그라다 파밀리아에 나무의 모양을 사용했다. 그것이 그가 자연의 아름다움을 실내로 들여온 방식이다.","segs":[{"k":"ⓐ","en":"This is because the natural world is a beautiful place.","ko":"이것은 자연 세계가 아름다운 곳이기 때문이다.","ok":true,"fix":"","why":"‘This is because + 주어 + 동사’는 ‘이것은 ~하기 때문이다’라는 뜻이다. 따라서 적절하다."},{"k":"ⓑ","en":"The shapes in nature are very pleased to the eye.","ko":"자연 속의 모양들은 눈에 매우 즐겁다.","ok":false,"fix":"The shapes in nature are very pleasing to the eye.","why":"주어 The shapes(모양들)는 기뻐하는 쪽이 아니라 눈을 즐겁게 해 주는 쪽이다. 이럴 때는 현재분사(동사 + -ing, ~하게 하는)를 쓴다. pleased는 ‘기뻐하는’이라는 뜻이다. 따라서 pleased는 pleasing이 적절하다."},{"k":"ⓒ","en":"Such a building actually exists in London.","ko":"그런 건물이 실제로 런던에 있다.","ok":true,"fix":"","why":"such(그런)는 형용사로 명사 a building을 꾸민다. 주어 Such a building이 단수이므로 동사도 단수동사 exists(원형 exist 존재하다)로 맞췄다. 따라서 적절하다."},{"k":"ⓓ","en":"It is one of the most famous churches in the world.","ko":"그것은 세계에서 가장 유명한 성당 중 하나이다.","ok":true,"fix":"","why":"‘one of the + 복수명사’는 ‘~ 중 하나’라는 뜻이다. 따라서 one of the most famous churches는 적절하다."},{"k":"ⓔ","en":"That's how he brought the beauty of nature indoors.","ko":"그것이 그가 자연의 아름다움을 실내로 들여온 방식이다.","ok":true,"fix":"","why":"‘That is how + 주어 + 동사’는 ‘그것이 ~가 …한 방식이다’라는 뜻이다. ‘That is the way + 주어 + 동사’로도 쓸 수 있다. 따라서 적절하다."}],"opts":["ⓐ","ⓑ","ⓒ","ⓓ","ⓔ"],"vb":["pleased → 원형 please 기쁘게 하다 (pleased 기뻐하는, pleasing 즐겁게 하는)","exists → 원형 exist 존재하다","brought → 원형 bring 가져오다 (과거형 brought)","inspired → 원형 inspire 영감을 주다","imitates → 원형 imitate 모방하다"]},{"id":"g3-074","n":74,"u":2,"st":"다음 글의 ⓐ~ⓔ 중에서 어법상 어색한 것은?","ty":"틀린 것 찾기","core":"부사가 동사 수식 · help + 목적어 + 동사원형 · thanks to · be likely to","ans":[3],"kind":"seg","pol":"bad","body":"Big data is influencing almost all parts of our lives. <b class=\"lb\">ⓐ</b><u>It helps companies understand their customers' needs better and helps them sell more products.</u> It helps people avoid heavy traffic. <b class=\"lb\">ⓑ</b><u>Its uses are endless, and here are some interesting examples.</u><br>Disease Forecast<br>Did you know that health professionals can now forecast a disease just as weather experts forecast the weather? <b class=\"lb\">ⓒ</b><u>This is possible thanks to big data.</u> For example, when the flu season comes, people will buy more flu medicine. They will also search online about flu symptoms more. <b class=\"lb\">ⓓ</b><u>If this kind of data is analyzed wise, the spread of the flu can be predicted.</u><br>Crime Prevention<br>Thanks to big data, police can now predict crime before it happens. Through the analysis of big data about the type, time and place of crime, police can make a map of crime hot spots. <b class=\"lb\">ⓔ</b><u>This map identifies when and where crime is most likely to happen.</u> Police can prevent further crime by focusing on the areas and the times this map predicts.","bko":"빅데이터는 우리 삶의 거의 모든 부분에 영향을 미치고 있다. 그것은 기업이 고객의 필요를 더 잘 이해하고 더 많은 제품을 팔도록 도와준다. 또 사람들이 심한 교통 체증을 피하도록 도와준다. 그 쓰임새는 무궁무진하며, 여기 흥미로운 예가 몇 가지 있다.\n질병 예측\n보건 전문가들이 기상 전문가들이 날씨를 예측하는 것처럼 이제 질병을 예측할 수 있다는 것을 알고 있었는가? 이것은 빅데이터 덕분에 가능하다. 예를 들어 독감 철이 오면 사람들은 독감약을 더 많이 살 것이다. 또 독감 증상에 대해 온라인에서 더 많이 검색할 것이다. 이런 종류의 데이터를 현명하게 분석하면 독감의 확산을 예측할 수 있다.\n범죄 예방\n빅데이터 덕분에 경찰은 이제 범죄가 일어나기 전에 예측할 수 있다. 범죄의 종류, 시간, 장소에 관한 빅데이터를 분석하여 경찰은 범죄 다발 지역 지도를 만들 수 있다. 이 지도는 범죄가 언제 어디서 일어날 가능성이 가장 높은지를 알려 준다. 경찰은 이 지도가 예측하는 지역과 시간대에 집중함으로써 추가 범죄를 막을 수 있다.","segs":[{"k":"ⓐ","en":"It helps companies understand their customers' needs better and helps them sell more products.","ko":"그것은 기업이 고객의 필요를 더 잘 이해하고 더 많은 제품을 팔도록 도와준다.","ok":true,"fix":"","why":"help(돕다)는 ‘help + 목적어 + 동사원형 또는 to부정사’ 꼴로 쓰고, 목적어와 목적보어가 능동 관계(기업이 이해하다, 기업이 팔다)일 때 알맞다. 등위접속사 and가 두 절(It helps ~ / (it) helps them sell ~)을 같은 모양으로 이어 준다. 따라서 적절하다."},{"k":"ⓑ","en":"Its uses are endless, and here are some interesting examples.","ko":"그것의 쓰임새는 끝이 없고, 여기 흥미로운 예가 몇 가지 있다.","ok":true,"fix":"","why":"소유격 Its가 명사 uses(쓰임새)를 꾸며 주어가 되었다. ‘Here + be동사 + 주어’는 ‘여기 ~가 있다’라는 뜻이고 주어 some interesting examples가 복수이므로 복수동사 are가 알맞다. 따라서 적절하다."},{"k":"ⓒ","en":"This is possible thanks to big data.","ko":"이것은 빅데이터 덕분에 가능하다.","ok":true,"fix":"","why":"thanks to ~는 ‘~ 덕분에’라는 뜻이다. 따라서 적절하다."},{"k":"ⓓ","en":"If this kind of data is analyzed wise, the spread of the flu can be predicted.","ko":"이런 종류의 데이터가 현명하게 분석되면, 독감의 확산을 예측할 수 있다.","ok":false,"fix":"If this kind of data is analyzed wisely, the spread of the flu can be predicted.","why":"동사 is analyzed(분석되다)를 꾸며 ‘어떻게 분석되는지’를 말해야 하므로 형용사 wise(현명한)가 아니라 부사 wisely(현명하게)를 써야 한다. 따라서 wise는 wisely가 적절하다."},{"k":"ⓔ","en":"This map identifies when and where crime is most likely to happen.","ko":"이 지도는 범죄가 언제 어디서 일어날 가능성이 가장 높은지를 알려 준다.","ok":true,"fix":"","why":"타동사(목적어가 필요한 동사) identifies(원형 identify 확인하다)의 목적어로 when and where crime is most likely to happen이라는 의문사절이 쓰였다. ‘be likely to + 동사원형’은 ‘~할 것 같다, ~할 가능성이 있다’라는 뜻이다. 따라서 적절하다."}],"opts":["ⓐ","ⓑ","ⓒ","ⓓ","ⓔ"],"vb":["helps → 원형 help 돕다","sell → 원형 sell 팔다","avoid → 원형 avoid 피하다","forecast → 원형 forecast 예측하다","analyzed → 원형 analyze 분석하다","identifies → 원형 identify 확인하다","happen → 원형 happen 일어나다"]},{"id":"g3-075","n":75,"u":2,"st":"다음 글의 ⓐ~ⓔ 중, 문장 내 어법의 쓰임이 적절하지 않은 것은?","ty":"틀린 것 찾기","core":"지각동사 see + 목적어 + 동사원형 · 접속사 that · 간접의문문 · 형용사는 명사를 수식 · the 비교급 ~, the 비교급 ~","ans":[3],"kind":"seg","pol":"bad","body":"The Tree-Book-Tree Project<br>This is the most amazing book that I have ever seen. After you finish reading this book, plant it and water it. You will see new leaves <b class=\"lb\">ⓐ</b><u>grow</u> on the book. In some bookstores in my town, you can see a copy of this book producing new leaves. The secret is <b class=\"lb\">ⓑ</b><u>that</u> the book has seeds in each page. These tiny seeds change the book into a tree. This book was made by a small children's book publisher in Argentina. Though the company does not print this book anymore, this special project makes us think about <b class=\"lb\">ⓒ</b><u>where books come from.</u><br>These are just a few of the unique books you can find. <b class=\"lb\">ⓓ</b><u>What other unique</u> do you want books to make? What special project would you like to do with the books? The bigger your imagination is, <b class=\"lb\">ⓔ</b><u>the more wonderful</u> your books will become.","bko":"나무-책-나무 프로젝트\n이것은 내가 지금까지 본 것 중 가장 놀라운 책이다. 이 책을 다 읽은 뒤에는 그것을 심고 물을 주어라. 책에서 새 잎이 자라는 것을 보게 될 것이다. 내가 사는 마을의 몇몇 서점에서는 이 책이 새 잎을 내고 있는 것을 볼 수 있다. 비밀은 책의 쪽마다 씨앗이 들어 있다는 것이다. 이 작은 씨앗들이 책을 나무로 바꾼다. 이 책은 아르헨티나의 한 작은 어린이책 출판사에서 만들었다. 그 회사는 더 이상 이 책을 인쇄하지 않지만, 이 특별한 프로젝트는 우리가 책이 어디에서 오는지 생각해 보게 한다.\n이것들은 여러분이 찾을 수 있는 독특한 책들 중 극히 일부이다. 책이 어떤 다른 독특한 것을 만들기를 여러분은 원하는가? 책으로 어떤 특별한 프로젝트를 해 보고 싶은가? 상상력이 클수록 여러분의 책은 더욱 놀라워질 것이다.","segs":[{"k":"ⓐ","en":"grow","ko":"자라다","ok":true,"fix":"","why":"‘지각동사(see, 보다) + 목적어(new leaves) + 목적보어’에서 목적어와 목적보어가 능동 관계(잎이 자라다)이면 목적보어는 동사원형이나 현재분사로 쓴다. 따라서 grow(원형 grow 자라다)는 적절하다."},{"k":"ⓑ","en":"that","ko":"~라는 것","ok":true,"fix":"","why":"is동사의 보어(주어를 설명하는 말) 자리에 절이 올 때 그 절을 이끄는 접속사 that(~라는 것)이 알맞다. 따라서 적절하다."},{"k":"ⓒ","en":"where books come from.","ko":"책이 어디에서 오는지.","ok":true,"fix":"","why":"think about(~에 대해 생각하다) 뒤에 의문사절이 올 때는 ‘의문사 + 주어 + 동사’의 간접의문문(의문문이 문장 속에 들어간 것) 어순을 쓴다. 따라서 where books come from은 적절하다."},{"k":"ⓓ","en":"What other unique","ko":"어떤 다른 독특한","ok":false,"fix":"What other unique books","why":"other unique(다른 독특한)는 형용사 표현이어서 반드시 꾸밀 명사가 있어야 한다. 이 문장은 What other unique books do you want to make?(어떤 다른 독특한 책을 만들고 싶니?)가 되어야 한다. 따라서 What other unique 뒤에 books를 붙여 고쳐야 한다."},{"k":"ⓔ","en":"the more wonderful","ko":"더 놀라운","ok":true,"fix":"","why":"‘the + 비교급 + 주어 + 동사, the + 비교급 + 주어 + 동사’는 ‘~할수록 더 …하다’라는 뜻이다. 따라서 the more wonderful은 적절하다."}],"opts":["ⓐ","ⓑ","ⓒ","ⓓ","ⓔ"],"vb":["seen → 원형 see 보다 (과거분사 seen, have ever seen 본 적이 있다)","plant → 원형 plant 심다","water → 원형 water 물을 주다","make → 원형 make 만들다","come → 원형 come 오다"]},{"id":"g3-076","n":76,"u":2,"st":"다음 글의 ⓐ~ⓔ 중, 어법의 쓰임이 적절하지 않은 것은?","ty":"틀린 것 찾기","core":"관계대명사절 동사의 수 일치 · 부사적 용법 to부정사 · whether · 가주어 it · 과거분사 후치 수식","ans":[4],"kind":"seg","pol":"bad","body":"Garcia-Fuller said she was teaching her students how to tell fake news from real news.<br>\"One of the first steps is to slow down. If a story or a photo seems too good to be true, stop and think: Is there any evidence that <b class=\"lb\">ⓐ</b><u>supports</u> what the writer says? And where is this coming from?\"<br>Garcia-Fuller's students also learn how to tell fact from opinion in the news. \"Opinions are good <b class=\"lb\">ⓑ</b><u>to read,</u>\" said 15-year-old McKenzie Campbell, \"but you also have to check <b class=\"lb\">ⓒ</b><u>whether</u> they are based on facts.\"<br>Garcia-Fuller also said that sometimes it can be very hard <b class=\"lb\">ⓓ</b><u>to be</u> a smart news reader. She tests her students with a website that appears to provide information on an animal <b class=\"lb\">ⓔ</b><u>calling</u> a tree octopus.","bko":"가르시아-풀러는 자신이 학생들에게 가짜 뉴스와 진짜 뉴스를 구별하는 방법을 가르치고 있다고 말했다.\n“첫 번째 단계 중 하나는 속도를 늦추는 것입니다. 어떤 기사나 사진이 너무 좋아서 사실 같지 않다면, 멈춰서 생각해 보세요. 글쓴이가 말하는 것을 뒷받침하는 증거가 있는가? 그리고 이것은 어디에서 나온 것인가?”\n가르시아-풀러의 학생들은 뉴스에서 사실과 의견을 구별하는 방법도 배운다. “의견은 읽기에 좋지만, 그것들이 사실에 근거하고 있는지도 확인해야 해요.”라고 15세의 매켄지 캠벨이 말했다.\n가르시아-풀러는 또한 똑똑한 뉴스 독자가 되는 것이 때로는 매우 어려울 수 있다고 말했다. 그녀는 나무 문어라고 불리는 동물에 대한 정보를 제공하는 것처럼 보이는 웹사이트로 학생들을 시험한다.","segs":[{"k":"ⓐ","en":"supports","ko":"뒷받침하다","ok":true,"fix":"","why":"주격 관계대명사(that)절의 동사는 선행사(앞에서 꾸밈을 받는 명사)의 수에 맞춰야 한다. 선행사 any evidence가 단수(셀 수 없는 명사)이므로 단수동사 supports(원형 support 뒷받침하다)가 알맞다. 따라서 적절하다."},{"k":"ⓑ","en":"to read,","ko":"읽기에","ok":true,"fix":"","why":"앞의 형용사 good(좋은)을 꾸며 ‘읽기에 좋은’이라는 뜻을 나타내는 부사적 용법의 to부정사이다. 따라서 적절하다."},{"k":"ⓒ","en":"whether","ko":"~인지 아닌지","ok":true,"fix":"","why":"whether는 뒤의 절을 이끌어 ‘~인지 아닌지’라는 뜻을 나타내는 접속사이다. check(확인하다)의 목적어절을 이끈다. 따라서 적절하다."},{"k":"ⓓ","en":"to be","ko":"~이 되는 것","ok":true,"fix":"","why":"it은 가주어(문장 앞에 대신 세운 주어)이고 to be a smart news reader가 진주어(진짜 주어)이다. 따라서 to be는 적절하다."},{"k":"ⓔ","en":"calling","ko":"불리는","ok":false,"fix":"called","why":"‘a tree octopus라고 불리는 동물’이라는 뜻이다. 동물은 ‘부르는’ 쪽이 아니라 ‘불리는’ 쪽이므로 수동의 뜻을 나타내는 과거분사(p.p., 동사의 세 번째 모양)를 써야 한다. 따라서 calling은 called(원형 call 부르다)가 적절하다."}],"opts":["ⓐ","ⓑ","ⓒ","ⓓ","ⓔ"],"vb":["teaching → 원형 teach 가르치다","tell → 원형 tell 구별하다","seems → 원형 seem ~처럼 보이다","supports → 원형 support 뒷받침하다","check → 원형 check 확인하다","appears → 원형 appear ~처럼 보이다","provide → 원형 provide 제공하다","calling → 원형 call 부르다 (과거분사 called)"]}];
